bool editar(const string& s,const string& t) {
    array<int,26> falta{};
    for(char c:t) ++falta[c-'A'];
    string mantida;
    for(int i=(int)s.size()-1;i>=0;--i){
        int c=s[i]-'A';
        if(falta[c]>0){ mantida+=s[i]; --falta[c]; }
    }
    reverse(mantida.begin(),mantida.end());
    return mantida==t;
}
